    /// Uses atomic write (temp file + rename) to prevent corruption on crash.
    fn save(&self) -> Result<()> {
        let temp_path = self.cache_file.with_extension("json.tmp");

        if let Some(parent) = self.cache_file.parent() {
            std::fs::create_dir_all(parent).context("Failed to create config directory")?;
        }

        let json = serde_json::to_string_pretty(&self.data)
            .context("Failed to serialize package cache")?;

        // Write to temp file first
        std::fs::write(&temp_path, &json).context("Failed to write temp package cache")?;

        // Atomic rename (on POSIX systems)
        std::fs::rename(&temp_path, &self.cache_file)
            .context("Failed to rename temp package cache")?;

        debug!("Package cache saved to {:?}", self.cache_file);
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn is_empty_returns_true_for_default_cache() {
        let cache = PackageCacheData::default();
        assert!(cache.is_empty());
    }

    #[test]
    fn is_empty_returns_false_when_entries_exist() {
        let mut cache = PackageCacheData::default();
        cache.entries.insert(
            "profile::package".to_string(),
            PackageCacheEntry {
                installed: true,
                last_checked: Utc::now(),
                check_command: None,
                output: None,
            },
        );
        assert!(!cache.is_empty());
    }

    #[test]
    fn is_empty_independent_of_schema_version() {
        let mut cache = PackageCacheData {
            version: 0,
            entries: HashMap::new(),
        };
        assert!(cache.is_empty());

        cache.entries.insert(
            "profile::package".to_string(),
            PackageCacheEntry {
                installed: false,
                last_checked: Utc::now(),
                check_command: Some("test".to_string()),
                output: Some("output".to_string()),
            },
        );
        assert!(!cache.is_empty());

        cache.version = 999;
        assert!(!cache.is_empty());

        cache.entries.clear();
        assert!(cache.is_empty());
    }

    #[test]
    fn is_empty_with_multiple_entries() {
        let mut cache = PackageCacheData::default();
        for i in 0..5 {
            cache.entries.insert(
                format!("profile::package{}", i),
                PackageCacheEntry {
                    installed: true,
                    last_checked: Utc::now(),
                    check_command: None,
                    output: None,
                },
            );
        }
        assert!(!cache.is_empty());

        cache.entries.clear();
        assert!(cache.is_empty());
    }
}

